-- IDs are generated by the application. This keeps the migration independent
-- from PostgreSQL extensions and allows the same IDs to be used in events.

BEGIN;

CREATE TABLE categories (
    -- Уникальный идентификатор категории, генерируемый приложением.
    id UUID PRIMARY KEY,
    -- Отображаемое название категории.
    name VARCHAR(255) NOT NULL CHECK (btrim(name) <> ''),
    -- Родительская категория для построения иерархии; NULL для корневой категории.
    parent_id UUID REFERENCES categories (id) ON DELETE RESTRICT,
    -- Порядок отображения категории среди категорий одного уровня.
    sort_order INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
    -- Версия категории для защиты от конкурентного изменения данных.
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    -- Дата и время создания категории.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Дата и время последнего изменения категории.
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (parent_id IS NULL OR parent_id <> id)
);

CREATE INDEX categories_parent_sort_idx
    ON categories (parent_id, sort_order, id);

CREATE TABLE products (
    -- Уникальный идентификатор товара, генерируемый приложением.
    id UUID PRIMARY KEY,
    -- Отображаемое название товара.
    name VARCHAR(255) NOT NULL,
    -- Описание товара для каталога и карточки товара.
    description TEXT NOT NULL DEFAULT '',
    -- Текущая цена товара в минимальных единицах валюты, например в копейках.
    price_minor_units BIGINT NOT NULL CHECK (price_minor_units >= 0),
    -- Код валюты текущей цены товара в формате ISO 4217.
    currency_code VARCHAR(3) NOT NULL
        CHECK (currency_code ~ '^[A-Z]{3}$'),
    -- Подпись одной ценовой единицы, например «шт» или «10 штук».
    -- Пустая строка означает, что подписи нет.
    unit_of_measure VARCHAR(64) NOT NULL DEFAULT '',
    -- Минимальное количество ценовых единиц в одной позиции заказа.
    -- 0 означает, что минимума нет.
    min_order_quantity INTEGER NOT NULL DEFAULT 0
        CHECK (min_order_quantity >= 0 AND min_order_quantity <= 10000),
    -- Минимальная стоимость позиции в минимальных единицах валюты товара.
    -- NULL означает, что минимума по сумме нет.
    min_order_amount_minor_units BIGINT NULL
        CHECK (min_order_amount_minor_units IS NULL OR min_order_amount_minor_units >= 1),
    -- Доступность товара: доступен, закончился или скрыт в архиве.
    availability VARCHAR(32) NOT NULL
        CHECK (availability IN ('available', 'out_of_stock', 'archived')),
    -- Версия товара для защиты от конкурентного изменения данных.
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    -- Дата и время создания товара.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Дата и время последнего изменения товара.
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX products_availability_created_idx
    ON products (availability, created_at DESC, id);

CREATE INDEX products_name_idx
    ON products (lower(name));

-- Изображения товаров не входят в MVP. Схема сохранена для следующей итерации.
/*
CREATE TABLE product_images (
    -- Уникальный идентификатор изображения товара.
    id UUID PRIMARY KEY,
    -- Товар, к которому относится изображение.
    product_id UUID NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    -- Адрес файла изображения, доступный клиентскому приложению.
    url TEXT NOT NULL CHECK (btrim(url) <> ''),
    -- Альтернативный текст изображения для доступности и ошибки загрузки.
    alt TEXT NOT NULL DEFAULT '',
    -- Порядок отображения изображения в карточке товара.
    sort_order INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
    -- Дата и время добавления изображения.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (product_id, sort_order)
);
*/

CREATE TABLE product_categories (
    -- Товар, включённый в категорию.
    product_id UUID NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    -- Категория, в которую включён товар.
    category_id UUID NOT NULL REFERENCES categories (id) ON DELETE RESTRICT,
    PRIMARY KEY (product_id, category_id)
);

CREATE INDEX product_categories_category_idx
    ON product_categories (category_id, product_id);

CREATE TABLE carts (
    -- Уникальный идентификатор корзины, генерируемый приложением.
    id UUID PRIMARY KEY,
    -- Хеш секретного токена, подтверждающего доступ к анонимной корзине.
    token_hash BYTEA NOT NULL UNIQUE CHECK (octet_length(token_hash) > 0),
    -- Состояние корзины: открыта, оформлена или просрочена.
    status VARCHAR(32) NOT NULL DEFAULT 'open'
        CHECK (status IN ('open', 'checked_out', 'expired')),
    -- Код валюты всех товаров и итоговой суммы корзины в формате ISO 4217.
    currency_code VARCHAR(3) NOT NULL
        CHECK (currency_code ~ '^[A-Z]{3}$'),
    -- Версия корзины для защиты от конкурентного изменения состава.
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    -- Дата и время создания корзины.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Дата и время последнего изменения корзины.
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Дата и время, после которых открытую корзину можно пометить просроченной.
    expires_at TIMESTAMPTZ NOT NULL,
    CHECK (expires_at > created_at)
);

CREATE INDEX carts_open_expiration_idx
    ON carts (expires_at, id)
    WHERE status = 'open';

CREATE TABLE cart_items (
    -- Уникальный идентификатор позиции корзины.
    id UUID PRIMARY KEY,
    -- Корзина, которой принадлежит позиция.
    cart_id UUID NOT NULL REFERENCES carts (id) ON DELETE CASCADE,
    -- Товар каталога, добавленный в корзину.
    product_id UUID NOT NULL REFERENCES products (id) ON DELETE RESTRICT,
    -- Количество единиц товара в корзине.
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    -- Дата и время добавления позиции в корзину.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Дата и время последнего изменения количества позиции.
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (cart_id, product_id)
);

CREATE INDEX cart_items_product_idx
    ON cart_items (product_id);

CREATE TABLE admin_users (
    -- Уникальный идентификатор пользователя административного кабинета.
    id UUID PRIMARY KEY,
    -- Регистронезависимый логин администратора для входа в кабинет.
    login VARCHAR(255) NOT NULL CHECK (btrim(login) <> ''),
    -- Безопасный хеш пароля администратора; исходный пароль не хранится.
    password_hash TEXT NOT NULL CHECK (btrim(password_hash) <> ''),
    -- Имя администратора, отображаемое в кабинете и истории изменений.
    display_name VARCHAR(255) NOT NULL CHECK (btrim(display_name) <> ''),
    -- Признак того, что администратору разрешена работа в кабинете.
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    -- Дата и время создания учётной записи администратора.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Дата и время последнего изменения учётной записи администратора.
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX admin_users_login_unique_idx
    ON admin_users (lower(login));

CREATE TABLE admin_user_roles (
    -- Администратор, которому назначена роль.
    admin_user_id UUID NOT NULL
        REFERENCES admin_users (id) ON DELETE CASCADE,
    -- Роль, определяющая набор разрешённых административных операций.
    role VARCHAR(32) NOT NULL CHECK (role IN ('manager', 'admin')),
    -- Дата и время назначения роли администратору.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (admin_user_id, role)
);

CREATE TABLE admin_sessions (
    -- Уникальный идентификатор сессии администратора.
    id UUID PRIMARY KEY,
    -- Администратор, которому принадлежит сессия.
    admin_user_id UUID NOT NULL
        REFERENCES admin_users (id) ON DELETE CASCADE,
    -- Хеш refresh-токена для безопасного продления сессии.
    refresh_token_hash BYTEA NOT NULL UNIQUE
        CHECK (octet_length(refresh_token_hash) > 0),
    -- Дата и время окончательного истечения refresh-токена.
    expires_at TIMESTAMPTZ NOT NULL,
    -- Дата и время принудительного завершения сессии; NULL для активной сессии.
    revoked_at TIMESTAMPTZ,
    -- Дата и время создания сессии.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (expires_at > created_at),
    CHECK (revoked_at IS NULL OR revoked_at >= created_at)
);

CREATE INDEX admin_sessions_active_user_idx
    ON admin_sessions (admin_user_id, expires_at)
    WHERE revoked_at IS NULL;

CREATE TABLE orders (
    -- Внутренний уникальный идентификатор заказа.
    id UUID PRIMARY KEY,
    -- Уникальный человекочитаемый номер заказа, показываемый покупателю.
    number VARCHAR(64) NOT NULL UNIQUE CHECK (btrim(number) <> ''),
    -- Редактируемое название или метка заказа.
    name VARCHAR(255) NOT NULL DEFAULT '',
    -- Корзина, из которой оформлен заказ; одна корзина создаёт не более одного заказа.
    cart_id UUID NOT NULL UNIQUE REFERENCES carts (id) ON DELETE RESTRICT,
    -- Хеш секретного токена для просмотра заказа покупателем без авторизации.
    order_token_hash BYTEA NOT NULL UNIQUE
        CHECK (octet_length(order_token_hash) > 0),
    -- Ключ попытки оформления, предотвращающий создание дубликатов заказа.
    checkout_idempotency_key VARCHAR(128) NOT NULL UNIQUE
        CHECK (btrim(checkout_idempotency_key) <> ''),
    -- Хеш запроса для проверки повторного использования ключа идемпотентности.
    checkout_request_hash BYTEA NOT NULL
        CHECK (octet_length(checkout_request_hash) > 0),
    -- Имя покупателя или получателя заказа.
    customer_full_name VARCHAR(255) NOT NULL
        CHECK (btrim(customer_full_name) <> ''),
    -- Телефон покупателя для связи и подтверждения заказа.
    customer_phone VARCHAR(64) NOT NULL
        CHECK (btrim(customer_phone) <> ''),
    -- Необязательный адрес электронной почты покупателя.
    customer_email VARCHAR(320) NOT NULL DEFAULT '',
    -- Способ получения заказа. Покупатель оформляет только доставку курьером.
    delivery_method VARCHAR(32) NOT NULL
        CHECK (delivery_method = 'courier'),
    -- Город доставки.
    delivery_city VARCHAR(255) NOT NULL DEFAULT '',
    -- Адрес доставки.
    delivery_address TEXT NOT NULL DEFAULT '',
    -- Уточнение покупателя по адресу или способу доставки.
    delivery_comment TEXT NOT NULL DEFAULT '',
    -- День, в который покупатель ждёт доставку, по календарю магазина.
    delivery_date DATE NOT NULL,
    -- Общий комментарий покупателя к заказу.
    customer_comment TEXT NOT NULL DEFAULT '',
    -- Внутренний комментарий сотрудников, не предназначенный для покупателя.
    internal_comment TEXT NOT NULL DEFAULT '',
    -- Администратор, ответственный за обработку заказа.
    assigned_admin_id UUID REFERENCES admin_users (id) ON DELETE SET NULL,
    -- Текущий этап обработки заказа.
    status VARCHAR(32) NOT NULL DEFAULT 'new'
        CHECK (
            status IN (
                'new',
                'confirmed',
                'assembling',
                'ready',
                'in_delivery',
                'completed',
                'cancelled'
            )
        ),
    -- Итоговая стоимость заказа в минимальных единицах валюты.
    total_minor_units BIGINT NOT NULL CHECK (total_minor_units >= 0),
    -- Код валюты заказа и всех его позиций в формате ISO 4217.
    currency_code VARCHAR(3) NOT NULL
        CHECK (currency_code ~ '^[A-Z]{3}$'),
    -- Версия заказа для защиты от одновременного редактирования.
    version BIGINT NOT NULL DEFAULT 1 CHECK (version > 0),
    -- Дата и время оформления заказа.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Дата и время последнего изменения заказа.
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (id, currency_code),
    CHECK (
        btrim(delivery_city) <> ''
        AND btrim(delivery_address) <> ''
    )
);

CREATE INDEX orders_status_created_idx
    ON orders (status, created_at DESC, id);

CREATE INDEX orders_assigned_admin_created_idx
    ON orders (assigned_admin_id, created_at DESC, id)
    WHERE assigned_admin_id IS NOT NULL;

CREATE INDEX orders_customer_phone_idx
    ON orders (customer_phone);

-- Заказы, которые занимают слот доставки в выбранный день.
CREATE INDEX orders_delivery_date_idx
    ON orders (delivery_date)
    WHERE status <> 'cancelled';

CREATE INDEX orders_delivery_city_date_idx
    ON orders (lower(btrim(delivery_city)), delivery_date)
    WHERE status <> 'cancelled';

-- Город или посёлок, в который магазин возит заказы.
CREATE TABLE delivery_places (
    id UUID PRIMARY KEY,
    -- Название так, как его видит покупатель.
    name VARCHAR(255) NOT NULL CHECK (btrim(name) <> ''),
    -- Ключ для уникальности и поиска без учёта регистра и крайних пробелов.
    name_key VARCHAR(255) NOT NULL UNIQUE CHECK (name_key <> ''),
    -- Сколько адресов можно принять в один день. 0 закрывает место.
    daily_limit INTEGER NOT NULL CHECK (daily_limit >= 0 AND daily_limit <= 10000),
    -- all — каждый день, weekdays — понедельник–пятница, dates — только выбранные даты.
    schedule_kind VARCHAR(16) NOT NULL
        CHECK (schedule_kind IN ('all', 'weekdays', 'dates')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Конкретные дни доставки. Используются, когда schedule_kind = 'dates'.
CREATE TABLE delivery_place_dates (
    place_id UUID NOT NULL REFERENCES delivery_places (id) ON DELETE CASCADE,
    delivery_date DATE NOT NULL,
    PRIMARY KEY (place_id, delivery_date)
);

-- Отдельный лимит доставок на конкретный день.
-- Оформление заказа считает места по городу, а не по этой таблице.
CREATE TABLE delivery_day_limits (
    -- День доставки по календарю магазина.
    delivery_date DATE PRIMARY KEY,
    -- Сколько адресов можно принять в этот день. 0 закрывает день.
    delivery_limit INTEGER NOT NULL CHECK (delivery_limit >= 0),
    -- Дата и время последнего изменения лимита.
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE order_items (
    -- Уникальный идентификатор позиции заказа.
    id UUID PRIMARY KEY,
    -- Заказ, которому принадлежит позиция.
    order_id UUID NOT NULL,
    -- Исходный товар каталога; может стать NULL после удаления товара.
    product_id UUID REFERENCES products (id) ON DELETE SET NULL,
    -- Снимок названия товара на момент добавления или изменения позиции.
    product_name VARCHAR(255) NOT NULL CHECK (btrim(product_name) <> ''),
    -- Цена одной единицы товара в минимальных единицах валюты.
    unit_price_minor_units BIGINT NOT NULL
        CHECK (unit_price_minor_units >= 0),
    -- Код валюты позиции, совпадающий с валютой заказа.
    currency_code VARCHAR(3) NOT NULL
        CHECK (currency_code ~ '^[A-Z]{3}$'),
    -- Количество единиц товара в заказе.
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    -- Стоимость позиции: цена одной единицы, умноженная на количество.
    line_total_minor_units BIGINT NOT NULL
        CHECK (line_total_minor_units >= 0),
    -- Снимок подписи ценовой единицы на момент добавления позиции.
    -- Пустая строка означает, что подписи не было.
    unit_of_measure VARCHAR(64) NOT NULL DEFAULT '',
    -- Дата и время добавления позиции в заказ.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Дата и время последнего изменения позиции заказа.
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (order_id, currency_code)
        REFERENCES orders (id, currency_code) ON DELETE CASCADE,
    CHECK (line_total_minor_units = unit_price_minor_units * quantity)
);

CREATE INDEX order_items_order_idx
    ON order_items (order_id, created_at, id);

CREATE INDEX order_items_product_idx
    ON order_items (product_id)
    WHERE product_id IS NOT NULL;

CREATE TABLE order_events (
    -- Уникальный идентификатор события истории заказа.
    id UUID PRIMARY KEY,
    -- Заказ, к которому относится событие.
    order_id UUID NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
    -- Тип изменения данных, состава или статуса заказа.
    event_type VARCHAR(32) NOT NULL
        CHECK (
            event_type IN (
                'created',
                'details_changed',
                'item_added',
                'item_changed',
                'item_removed',
                'status_changed'
            )
        ),
    -- Администратор, выполнивший изменение; NULL для системного события.
    actor_admin_id UUID REFERENCES admin_users (id) ON DELETE RESTRICT,
    -- Пояснение администратора или системы к событию.
    comment TEXT NOT NULL DEFAULT '',
    -- Дата и время возникновения события.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX order_events_order_created_idx
    ON order_events (order_id, created_at, id);

CREATE TABLE order_event_changes (
    -- Последовательный идентификатор отдельного изменения поля.
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    -- Событие заказа, в рамках которого изменилось поле.
    order_event_id UUID NOT NULL
        REFERENCES order_events (id) ON DELETE CASCADE,
    -- Путь изменённого поля в модели заказа.
    field_path TEXT NOT NULL CHECK (btrim(field_path) <> ''),
    -- Текстовое представление значения поля до изменения.
    old_value TEXT NOT NULL DEFAULT '',
    -- Текстовое представление значения поля после изменения.
    new_value TEXT NOT NULL DEFAULT ''
);

CREATE INDEX order_event_changes_event_idx
    ON order_event_changes (order_event_id, id);

-- One row represents delivery through one notification channel. The channel is
-- intentionally not constrained so a new notifier does not require a schema
-- migration.
CREATE TABLE notification_outbox (
    -- Уникальный идентификатор задания на отправку уведомления.
    id UUID PRIMARY KEY,
    -- Заказ, событие которого требуется отправить во внешний канал.
    order_id UUID NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
    -- Тип уведомления, например создание или изменение заказа.
    notification_type VARCHAR(64) NOT NULL
        CHECK (btrim(notification_type) <> ''),
    -- Имя канала отправки, например telegram или whatsapp.
    channel VARCHAR(64) NOT NULL CHECK (btrim(channel) <> ''),
    -- Ключ, предотвращающий повторную отправку события через один канал.
    deduplication_key VARCHAR(255) NOT NULL
        CHECK (btrim(deduplication_key) <> ''),
    -- Зафиксированные данные уведомления в формате JSON.
    payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'),
    -- Состояние доставки уведомления.
    status VARCHAR(32) NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'processing', 'sent', 'failed')),
    -- Количество уже выполненных попыток отправки.
    attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    -- Момент, начиная с которого можно выполнить следующую попытку.
    available_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Момент захвата задания обработчиком для восстановления зависших заданий.
    locked_at TIMESTAMPTZ,
    -- Последняя безопасная ошибка отправки без секретов и персональных данных.
    last_error TEXT NOT NULL DEFAULT '',
    -- Дата и время создания задания на отправку.
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Дата и время последнего изменения состояния задания.
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- Дата и время успешной отправки; NULL до отправки.
    sent_at TIMESTAMPTZ,
    UNIQUE (channel, deduplication_key),
    CHECK (sent_at IS NULL OR sent_at >= created_at)
);

CREATE INDEX notification_outbox_pending_idx
    ON notification_outbox (available_at, created_at, id)
    WHERE status = 'pending';

CREATE INDEX notification_outbox_order_idx
    ON notification_outbox (order_id, created_at, id);

COMMIT;

